<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {showToast} from 'vant';import {money} from '../data/demo';import {useLoanStore} from '../stores/loan';import PageNav from '../components/PageNav.vue';const store=useLoanStore(),router=useRouter(),agreed=ref(false);const submit=()=>{if(!agreed.value)return showToast('请阅读并同意相关协议');router.replace(`/application/${store.applicationId}`)}</script>
<template><main class="page"><PageNav title="确认借款"/><section class="contract-summary"><p>到账金额</p><strong>{{money(store.loanDraft.amount)}}</strong><span>预计 10 分钟内到账（演示）</span></section><van-cell-group inset><van-cell title="借款期数" :value="`${store.loanDraft.term} 期`"/><van-cell title="收款银行卡" :value="store.loanDraft.bank"/><van-cell title="还款方式" value="按期等额还款"/><van-cell title="提前还款" value="无额外手续费"/></van-cell-group><section class="agreement-list"><h2>请阅读并确认</h2><van-cell title="《个人借款合同》" is-link/><van-cell title="《征信查询授权书》（演示）" is-link/><van-cell title="《个人信息使用授权书》" is-link/><van-checkbox v-model="agreed" shape="square">我已阅读并同意上述协议，确认借款信息无误</van-checkbox></section><van-button class="fixed-cta" round block type="primary" @click="submit">同意协议并提交申请</van-button></main></template>
